 // Preserve the original urgent envelope and original input, before age or review checks.
 if(N.currentEmergency(null,p)||P.emergency(p,null))return base.build(p);
 const age=p.age||'unknown';if(!Object.hasOwn(base.ages,age))return {ok:false,code:'AGE_INVALID',message:'Selecione uma faixa etária válida.',error:'Selecione uma faixa etária válida.'};
