function audit(){const prior=base.audit(),issues=[...(prior.issues||[])];if(topics.length!==219||new Set(topics.map(t=>t.key)).size!==219)issues.push('curated-urgent-card-count');for(const t of data.topics){const r=build({diagnosis:t.key,age:'unknown',reviewed:false});if(!r.ok||r.mode!=='guidance'||r.topic!==t.key||r.sections.length!==6||r.refs.some(id=>!sources[id]))issues.push('curated-urgent-body:'+t.key);}return {...prior,ok:!issues.length,issues,topics:topics.length,urgent:topics.filter(t=>t.urgency).length,curatedUrgent:{newCards:3,newControls:0,fullCoverageVerified:false}};}
